def solve():
    memo = {}

    def get_cookies(board):
        board = tuple(sorted(board))
        if board in memo:
            return memo[board]

        s = sum(board)
        if not board:
            return 0
        max_val = max(board)
        if max_val > s - max_val or s == 0:
            return len(board)

        possible_results = []
        n = len(board)
        for i in range(n):
            for j in range(i + 1, n):
                x = board[i]
                y = board[j]

                # B chooses the minimum of these two
                res_x_plus_y = get_cookies(list(board[:i] + board[i+1:j] + board[j:] + [x+y]))
                res_abs_diff = get_cookies(list(board[:i] + board[i+1:j] + board[j:] + [abs(x-y)]))

                possible_results.append(min(res_x_plus_y, res_abs_diff))

        res = max(possible_results)
        memo[board] = res
        return res

    for n in range(1, 11):
        memo = {}
        initial_board = tuple([1] * n)
        print(f"n={n}, cookies={get_cookies(initial_board)}")

